body.l-collage main {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 22px;
  max-width: 1080px; margin: 0 auto; padding: 50px 24px 24px;
}
body.l-collage main section {
  padding: 28px; margin: 0; max-width: none;
  border: 1.5px solid var(--border); background: var(--surface);
}
body.l-collage #projects { grid-column: 1 / 5; }
body.l-collage #skills { grid-column: 5 / 7; grid-row: span 2; }
body.l-collage #about { grid-column: 1 / 3; transform: rotate(-.7deg); }
body.l-collage #blog { grid-column: 3 / 5; transform: rotate(.5deg); }
body.l-collage #contact { grid-column: 5 / 7; transform: rotate(-.4deg); }
